using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Automation;
using System.Windows.Media;
using System.Windows.Shapes;
namespace MochiDesktop {
 public static class MediaPresentation {
  public static string PrimaryAction(MediaSessionInfo item){if(item==null)return null;if(string.Equals(item.Playback,"Playing",StringComparison.OrdinalIgnoreCase)&&item.CanPause)return "pause";if(item.CanPlay)return "play";return item.CanPause?"pause":null;}
 }
 public sealed class MediaWindow : MochiDialog {
  readonly ComboBox players=new ComboBox();
  readonly TextBlock song=MochiTheme.Text("A little soundtrack",19,MochiTheme.Ink,true),artist=MochiTheme.Text("Start a song in your browser or music app.",12,MochiTheme.Muted,false),source=MochiTheme.Text("No player selected",11,MochiTheme.Muted,false),playback=MochiTheme.Text("READY WHEN YOU ARE",9,MochiTheme.Purple,true),status=MochiTheme.Text("",12,MochiTheme.Muted,false),updated=MochiTheme.Text("On-demand controls / no background polling",10,MochiTheme.Muted,false);
  readonly Dictionary<string,Button> controls=new Dictionary<string,Button>();
  readonly Button refresh,primary;bool busy,closed;
  public MediaWindow(CompanionWindow owner,string initialAction=null):base(owner,"Mochi - media controls",650){
   var eyebrow=MochiTheme.Text("MUSIC / YOUR ACTIVE PLAYERS",10,MochiTheme.Purple,true);eyebrow.Margin=new Thickness(0,0,0,8);Panel.Children.Add(eyebrow);Heading("Your music, close by");
   var art=new Border{Width=76,Height=88,CornerRadius=new CornerRadius(18),Background=MochiTheme.Lavender,Child=Glyph("music",MochiTheme.Purple,34),Margin=new Thickness(0,0,15,0)};
   var info=new StackPanel{VerticalAlignment=VerticalAlignment.Center};song.TextWrapping=TextWrapping.Wrap;song.MaxHeight=58;artist.TextWrapping=TextWrapping.Wrap;artist.Margin=new Thickness(0,5,0,6);source.TextWrapping=TextWrapping.Wrap;info.Children.Add(song);info.Children.Add(artist);info.Children.Add(source);
   var cover=new Grid();cover.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});cover.ColumnDefinitions.Add(new ColumnDefinition());cover.Children.Add(art);Grid.SetColumn(info,1);cover.Children.Add(info);var nowPlaying=MochiTheme.Card(cover);nowPlaying.Margin=new Thickness(0,2,0,10);Panel.Children.Add(nowPlaying);
   var badge=new Border{Background=MochiTheme.ColorBrush("#EEE7F6"),CornerRadius=new CornerRadius(8),Padding=new Thickness(9,5,9,5),HorizontalAlignment=HorizontalAlignment.Left,Child=playback};Panel.Children.Add(badge);
   Field("Choose a player",players);players.MinHeight=40;players.Margin=new Thickness(0,0,0,9);
   var transport=new Grid{Margin=new Thickness(9,8,9,13)};transport.ColumnDefinitions.Add(new ColumnDefinition());transport.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.4,GridUnitType.Star)});transport.ColumnDefinitions.Add(new ColumnDefinition());
   var previous=Transport("previous","Previous",delegate{var pending=Control("previous");});controls["previous"]=previous;transport.Children.Add(previous);
   primary=MochiTheme.Button("Play selected player",delegate{var pending=Control("toggle");},true);primary.Width=86;primary.Height=86;primary.Padding=new Thickness(0);primary.HorizontalAlignment=HorizontalAlignment.Center;primary.Template=RoundTemplate();Grid.SetColumn(primary,1);transport.Children.Add(primary);
   var next=Transport("next","Next",delegate{var pending=Control("next");});controls["next"]=next;Grid.SetColumn(next,2);transport.Children.Add(next);Panel.Children.Add(transport);
   var tools=new Grid();tools.ColumnDefinitions.Add(new ColumnDefinition());tools.ColumnDefinitions.Add(new ColumnDefinition());var stop=MochiTheme.Button("Stop",delegate{var pending=Control("stop");},false);stop.Margin=new Thickness(0,0,4,0);controls["stop"]=stop;tools.Children.Add(stop);refresh=MochiTheme.Button("Refresh players",delegate{var pending=Refresh(true);},false);refresh.Margin=new Thickness(4,0,0,0);Grid.SetColumn(refresh,1);tools.Children.Add(refresh);Panel.Children.Add(tools);
   status.Margin=new Thickness(0,13,0,8);Panel.Children.Add(status);updated.Margin=new Thickness(0,0,0,6);Panel.Children.Add(updated);Note("Start playback once in a compatible browser or music app, then choose it here. Unavailable controls stay disabled. Volume and seeking remain in that player.");
   players.SelectionChanged+=delegate{UpdateControls();};Loaded+=async delegate{await Refresh(true);if(initialAction!=null&&players.SelectedItem!=null)await Control(initialAction);};Closed+=delegate{closed=true;};UpdateControls();
  }
  static FrameworkElement Glyph(string kind,Brush color,double size){string path=kind=="pause"?"M5,3 L10,3 L10,21 L5,21 Z M15,3 L20,3 L20,21 L15,21 Z":kind=="previous"?"M18,3 L7,12 L18,21 Z M3,3 L5,3 L5,21 L3,21 Z":kind=="next"?"M6,3 L17,12 L6,21 Z M19,3 L21,3 L21,21 L19,21 Z":kind=="music"?"M9,5 L21,2 L21,17 C21,23 12,24 12,19 C12,16 15,14 18,15 L18,7 L9,10 L9,20 C9,26 0,26 0,21 C0,18 3,16 6,17 L6,6 Z":"M6,3 L21,12 L6,21 Z";return new Viewbox{Width=size,Height=size,Child=new Path{Data=Geometry.Parse(path),Fill=color,Stretch=Stretch.Uniform}};}
  static Button Transport(string action,string label,Action invoke){var b=MochiTheme.Button(label,invoke,false);b.Width=72;b.Height=64;b.Padding=new Thickness(9);b.HorizontalAlignment=HorizontalAlignment.Center;b.VerticalAlignment=VerticalAlignment.Center;var contents=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center};contents.Children.Add(Glyph(action,MochiTheme.Purple,21));var text=MochiTheme.Text(label,10,MochiTheme.Ink,true);text.Margin=new Thickness(0,6,0,0);contents.Children.Add(text);b.Content=contents;return b;}
  static ControlTemplate RoundTemplate(){var template=new ControlTemplate(typeof(Button));var border=new FrameworkElementFactory(typeof(Border));border.Name="disc";border.SetValue(Border.CornerRadiusProperty,new CornerRadius(43));border.SetValue(Border.BackgroundProperty,new TemplateBindingExtension(System.Windows.Controls.Control.BackgroundProperty));border.SetValue(Border.BorderBrushProperty,new TemplateBindingExtension(System.Windows.Controls.Control.BorderBrushProperty));border.SetValue(Border.BorderThicknessProperty,new Thickness(2));var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(content);template.VisualTree=border;var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(UIElement.OpacityProperty,.84,"disc"));template.Triggers.Add(hover);var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(UIElement.OpacityProperty,.4,"disc"));template.Triggers.Add(disabled);var focus=new Trigger{Property=UIElement.IsKeyboardFocusedProperty,Value=true};focus.Setters.Add(new Setter(Border.BorderBrushProperty,MochiTheme.Ink,"disc"));template.Triggers.Add(focus);return template;}
  void UpdateControls(){var item=players.SelectedItem as MediaSessionInfo;foreach(var pair in controls)pair.Value.IsEnabled=!busy&&NativeMedia.CanControl(item,pair.Key);string action=MediaPresentation.PrimaryAction(item);primary.IsEnabled=!busy&&action!=null;string label=action=="pause"?"Pause":"Play";AutomationProperties.SetName(primary,label+" selected player");primary.ToolTip=action==null?"Start a compatible player and refresh.":label+" in the selected Windows player";var center=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center};center.Children.Add(Glyph(action=="pause"?"pause":"play",Brushes.White,24));var caption=MochiTheme.Text(label,10,Brushes.White,true);caption.HorizontalAlignment=HorizontalAlignment.Center;caption.Margin=new Thickness(0,5,0,0);center.Children.Add(caption);primary.Content=center;players.IsEnabled=!busy;refresh.IsEnabled=!busy;song.Text=item==null?"A little soundtrack":string.IsNullOrWhiteSpace(item.Title)?item.App:item.Title;artist.Text=item==null?"Start a song in your browser or music app.":string.IsNullOrWhiteSpace(item.Artist)?"Your selected Windows player":item.Artist;source.Text=item==null?"No player selected":item.App;playback.Text=item==null?"READY WHEN YOU ARE":(item.Playback??"Unknown").ToUpperInvariant();}
  async Task Refresh(bool showStatus){if(busy||closed)return;busy=true;UpdateControls();var previous=players.SelectedItem as MediaSessionInfo;string selected=previous==null?null:previous.Id;if(showStatus)status.Text="Looking for active players...";try{List<MediaSessionInfo> items=await NativeMedia.ListAsync();if(closed)return;players.ItemsSource=items;players.SelectedItem=items.FirstOrDefault(item=>item.Id==selected)??items.FirstOrDefault();updated.Text="Reported by Windows / "+DateTime.Now.ToString("HH:mm");if(showStatus)status.Text=items.Count==0?"No active media session yet. Start playback, then refresh players.":items.Count+" player"+(items.Count==1?"":"s")+" available. Choose the one you want to control.";}catch(Exception error){if(!closed&&showStatus)status.Text=error.Message;}finally{busy=false;if(!closed)UpdateControls();}}
  async Task Control(string action){if(busy||closed)return;var item=players.SelectedItem as MediaSessionInfo;if(!NativeMedia.CanControl(item,action)){status.Text="This player does not offer that control. Use its own controls or choose another player.";return;}busy=true;UpdateControls();status.Text="Asking "+item.App+"...";try{bool accepted=await NativeMedia.ControlAsync(item.Id,action);if(!closed)status.Text=accepted?item.App+" accepted "+(action=="toggle"?"play/pause":action)+".":item.App+" declined "+(action=="toggle"?"play/pause":action)+". Use the player's controls, then refresh.";}catch(Exception error){if(!closed)status.Text=error.Message;}finally{busy=false;if(!closed)UpdateControls();}if(!closed)await Refresh(false);}
 }
}
